"""A24 clinic wiring: original choice indices and cancel behavior preserved."""
import copy,json,re,textwrap,zipfile,hashlib
from pathlib import Path
OUT=Path('tools/cosmetic-skins')
def load(n):return json.loads(Path('data/'+n+'.json').read_text(encoding='utf-8'))
targets=[(25,4),(45,1),(83,3),(99,2)];D={n:load(f'Map{n:03}')for n,_ in targets}
p=Path('js/plugins.js');source=p.read_text(encoding='utf-8');plugins=json.loads(re.search(r'var\s+\$plugins\s*=\s*(\[.*\]);',source,re.S)[1]);assert not any(q['name']=='ME_CosmeticSkins'for q in plugins)
with zipfile.ZipFile(OUT/'before.zip','x',zipfile.ZIP_DEFLATED)as z:
 for n in D:z.write(f'data/Map{n:03}.json')
 z.write('js/plugins.js');z.write('data/Actors.json')
def C(code,*p):return dict(code=code,indent=0,parameters=list(p))
def say(t):
 lines=textwrap.wrap(t,43);out=[]
 for i in range(0,len(lines),4):out+=[C(101,'',0,0,2)]+[C(401,line)for line in lines[i:i+4]]
 return out
body=say('Chromatic skin for Rex: two surface-coating projections. Mint Condition costs80 Credits to unlock; Ultraviolet Liability costs120. Preview first. Refitting and original appearance are free. No combat benefits. Your bad decisions remain factory-original.')+[C(355,'if (!ME.Cosmetics.open()) { $gameMessage.add("Bring Rex conscious in the walking party."); $gameMessage.add("Use his usual appearance for the fitting."); this.setWaitMode("message"); }')]
entries=[]
for n,id in targets:
 L=D[n]['events'][id]['pages'][0]['list'];h=next(c for c in L if c['code']==102 and c['indent']==0);index=len(h['parameters'][0]);assert 'Chromatic skin: Rex'not in h['parameters'][0];h['parameters'][0].append('Chromatic skin: Rex')
 i=next(i for i,c in enumerate(L)if c['code']==404 and c['indent']==0);L[i:i]=[C(402,index,'Chromatic skin: Rex')]+[dict(c,indent=c['indent']+1)for c in body]+[dict(C(0),indent=1)];entries.append(dict(map=n,event=id,choice=index,cancel=h['parameters'][1]))
 for pg in D[n]['events'][id]['pages'][1:]:assert not pg.get('list'),'Review additional service pages before adapting cosmetics.'
for n,m in D.items():Path(f'data/Map{n:03}.json').write_text(json.dumps(m,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
plugins.append(dict(name='ME_CosmeticSkins',status=True,description='Rex-only reversible chromatic appearance presets; no gameplay stats.',parameters={}));p.write_text('// Generated by RPG Maker.\n// Do not edit this file directly.\nvar $plugins =\n'+json.dumps(plugins,ensure_ascii=False,indent=2)+';\n',encoding='utf-8')
assets=[('characters','Rex_walk',576,384,48,48,12),('faces','Rex',576,288,144,144,1),('sv_actors','Rex',576,384,64,64,54)]
contract=[]
for folder,name,w,h,cw,ch,count in assets:
 path=Path('img')/folder/(name+'.png');contract.append(dict(path=str(path).replace('\\','/'),sha256=hashlib.sha256(path.read_bytes()).hexdigest(),width=w,height=h,cell=[cw,ch],usedCells=count,scale=1,pivot='native engine anchor; no repacking or per-frame fitting'))
(OUT/'manifest.json').write_text(json.dumps(dict(actor=1,entries=entries,presets=[dict(id='mint',hue=90,cost=80),dict(id='ultraviolet',hue=240,cost=120)],assets=contract,restoration='free',saveFields=['_meChromaticOwned','_meChromaticStyle'],completionLogTotal=37),indent=2),encoding='utf-8');print('Installed A24 skin catalog at four existing counters; verification pending.')
